def calculate_tax(amount, rate):
    """统一计税函数：返回税额。"""
    return amount * rate

def invoice_subtotal(amount):
    tax = calculate_tax(amount, 0.13)
    return amount + tax

def refund(amount):
    tax = calculate_tax(amount, 0.13)
    return amount - tax

def statement(amount):
    tax = calculate_tax(amount, 0.13)
    return {"gross": amount, "tax": tax}
